                    m.cellRefVol.push_back(refV);m.cellRefCentre.push_back(refC);
                    m.cellLevel.push_back(level);m.cellRank.push_back(rank);m.cellLeaf.push_back(leaf);
                    m.cellPiece.push_back(piece);++added;
                    if(traceCones)m.coneEvidenceParent.push_back(m.coneEvidenceParent[c]);
                    if(literalUnions)unionParent.push_back(unionParent[c]);
