                m.cellLevel.push_back(level);m.cellRank.push_back(rank);m.cellLeaf.push_back(leaf);m.cellPiece.push_back(piece);++added;
                if (traceCones) { m.coneEvidenceParent.push_back(m.coneEvidenceParent[c]); }
